#!/usr/bin/env python3
"""Build a documentation-only alias review from fixed local candidate records.
Does not change datasets, features, model artifacts, runtime code or game state.
"""
import collections,csv,hashlib,json,re
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3]
OUT=Path(__file__).resolve().parent
CANDIDATES=ROOT/'docs/audit/semantic_identity_candidates.json'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def read(p):return json.loads(p.read_text())
def norm(x):return re.sub('[^a-z0-9]+',' ',x.lower()).strip()
def spelling(x):
    tokens=norm(x).split()
    # Lexical suggestions only. Do not generalize St at the start of a school name.
    if tokens and tokens[-1]=='st':tokens[-1]='state'
    if tokens and tokens[-1]=='col':tokens[-1]='college'
    if tokens and tokens[0]=='ala':tokens[0]='alabama'
    if tokens and tokens[0]=='se':tokens[0]='southeast'
    if tokens==['miami','oh']:tokens=['miami','ohio']
    if tokens and tokens[-1]=='university' and len(tokens)>=3:tokens=tokens[:-1]
    return ' '.join(tokens)
SOURCES=[
 {'sourceId':'sf-trey-2021','publisher':'San Francisco 49ers','type':'official-team-report','url':'https://www.49ers.com/news/49ers-trey-lance-with-the-no-3-pick-in-the-2021-nfl-draft','publishedAtDisplay':'Apr 29, 2021 at 05:41 PM','publishedTimezone':'not stated in retrieved text','retrievedReference':'turn513618820view0','evidenceLocator':'Article heading and paragraph at retrieved lines 41–53','factualSummary':'Identifies Trey Lance as a North Dakota State quarterback chosen by San Francisco third overall in the 2021 draft.'},
 {'sourceId':'ndsu-trey-2021','publisher':'North Dakota State University Athletics','type':'official-university-report','url':'https://gobison.com/news/2021/4/29/football-san-francisco-49ers-draft-trey-lance-with-no-3-overall-pick','publishedAtDisplay':'4/29/2021 10:00:00 PM','publishedTimezone':'not stated in retrieved text','retrievedReference':'turn513618820view1','evidenceLocator':'Article heading/date and opening paragraph at retrieved lines 367–370','factualSummary':'Reports that San Francisco selected its North Dakota State quarterback Trey Lance third overall on April 29, 2021.'},
 {'sourceId':'rams-long-2019','publisher':'Los Angeles Rams','type':'official-team-report','url':'https://www.therams.com/news/a-look-at-each-pick-of-the-rams-2019-draft-class','publishedAtDisplay':'Apr 28, 2019 at 02:00 PM','retrievedReference':'turn428353609view0','evidenceLocator':'Retrieved lines 66–67','factualSummary':'Lists Michigan cornerback David Long as the Rams selection at pick 79 in 2019.'},
 {'sourceId':'titans-long-2019','publisher':'Tennessee Titans','type':'official-team-report','url':'https://www.tennesseetitans.com/news/titans-selected-west-virginia-linebacker-david-long-in-sixth-round','publishedAtDisplay':'Apr 27, 2019 at 02:55 PM','retrievedReference':'turn428353609view1','evidenceLocator':'Retrieved lines 58–60','factualSummary':'Reports West Virginia linebacker David Long selected by Tennessee at pick 188 in 2019.'},
 {'sourceId':'packers-johnson-2023','publisher':'Green Bay Packers','type':'official-team-report','url':'https://www.packers.com/news/2023-nfl-draft-packers-select-iowa-state-s-anthony-johnson-in-seventh-round-no-2','publishedAtDisplay':'Apr 29, 2023 at 05:20 PM','retrievedReference':'turn428353609view2','evidenceLocator':'Retrieved lines 59–60','factualSummary':'Reports Iowa State safety Anthony Johnson Jr. selected by Green Bay at pick 242 in 2023 after five years at Iowa State.'},
 {'sourceId':'saints-johnson-2023','publisher':'New Orleans Saints','type':'official-team-report','url':'https://www.neworleanssaints.com/news/new-orleans-saints-roster-undrafted-free-agents-2023-nfl-draft','publishedAtDisplay':'Apr 30, 2023 at 10:04 AM','retrievedReference':'turn428353609view3','evidenceLocator':'Retrieved lines 52 and 106–111; source search result also identifies 2019–20 Louisville and 2021–22 Virginia seasons','factualSummary':'Lists Virginia defensive back Anthony Johnson among New Orleans undrafted free agents after the 2023 draft.'},
]
for s in SOURCES:s.update({'retrievedOn':'2026-11-20','originalArchivedSnapshot':False,'originalHtmlSha256':None,'preservedMaterial':'source metadata and paraphrased factual finding only; not an original HTML archive'})
items=read(CANDIDATES);assert len(items)==53
classified=[]
for n,g in enumerate(items,1):
    rows=g['records'];name=rows[0]['name'];schools=[r['college']for r in rows]
    if g['year']==2021 and name=='Trey Lance':
        category='sourced-same-person';status='audited-postdraft-reference-alias';reason='Exact name and quarterback role; two primary reports identify the North Dakota State player as the 2021 pick 3. State/St. is the local school spelling difference.';sources=['sf-trey-2021','ndsu-trey-2021'];action='stage one exact-ID postdraft-reference alias only; do not apply now'
    elif g['year']==2019 and name=='David Long':
        category='distinct-people';status='sourced-do-not-merge';reason='Official team reports distinguish Michigan CB pick 79 and West Virginia LB pick 188 in the same draft.';sources=['rams-long-2019','titans-long-2019'];action='preserve both IDs; forbid name-only merging'
    elif g['year']==2023 and name=='Anthony Johnson':
        category='distinct-people';status='sourced-do-not-merge';reason='Official reports distinguish the five-year Iowa State player drafted by Green Bay from Virginia player signed undrafted by New Orleans in the same class.';sources=['packers-johnson-2023','saints-johnson-2023'];action='preserve both IDs; forbid name-only merging'
    elif len({spelling(s)for s in schools})==1:
        category='school-spelling-abbreviation-candidate';status='unverified-suggestion';reason='Exact normalized player name; schools become equal under narrow terminal St./State or Col./College, Ala./Alabama, SE/Southeast, OH/Ohio, or University suffix spelling rules. This is not independently sourced identity verification.';sources=[];action='review primary player/draft sources before staging any ID alias'
    else:
        category='unresolved';status='unverified-suggestion';reason='Exact normalized name alone is insufficient. Schools require an institution acronym, missing geographic qualifier, initials or nontrivial historical-name interpretation beyond the narrow lexical rules.';sources=[];action='hold separate; obtain primary identity and school evidence'
    classified.append({'groupId':f'cross-pool-{n:03d}','year':g['year'],'name':name,'classification':category,'evidenceStatus':status,'reason':reason,'sourceIds':sources,'action':action,'narrowSchoolKeys':[spelling(s)for s in schools],'positionLabelsDiffer':len({r['position']for r in rows})>1,'records':rows})
counts=dict(collections.Counter(x['classification']for x in classified))
review={'schemaVersion':1,'reviewVersion':'cross-pool-documentation-review-v1','reviewedOn':'2026-11-20','scope':'All 53 normalized-exact-name cross-eligibility candidate groups; not an exhaustive identity-resolution audit.','input':{'path':str(CANDIDATES.relative_to(ROOT)),'sha256':sha(CANDIDATES)},'classificationCounts':counts,'rules':{'sourceRequiredForApplication':True,'spellingRulesAreUnverifiedSuggestions':True,'sameNameAloneNeverSufficient':True,'newEligibilityOrMeasurementClaims':False},'sources':SOURCES,'groups':classified,'limitations':['Only one same-person identity alias is audited and staged. Other suggested matches lack individual primary-source verification.','Name-change pairs Gregory/Greg Rousseau and Jayson/Odafe Oweh are outside the original 53 normalized-exact-name groups.','Position-label differences are preserved as evidence and are not silently resolved by a school alias.','All retrieved sources are live pages, not original archived snapshots.']}
(OUT/'cross_pool_classification.json').write_text(json.dumps(review,indent=2)+'\n')
scenarioPath=ROOT/'data/processed/scenario-2021.json';scenario=read(scenarioPath);byid={p['id']:p for p in scenario['prospects']}
canonical='p2021-4a3e07404f';alias='p2021-ref-e9aacb6df1';actual=next(p for p in scenario['actualPicks']if p['overall']==3)
assert actual=={'overall':3,'round':1,'team':'SF','prospectId':alias}
assert byid[canonical]['eligibilitySource']=='combine-participant' and byid[alias]['eligibilitySource']=='retrospective-draft-record'
assert all(byid[i]['name']=='Trey Lance' and byid[i]['position']=='QB'for i in [canonical,alias])
rawPath=ROOT/'data/raw/draft_picks.csv'
with rawPath.open(newline='')as f:raw=next(r for r in csv.DictReader(f)if r['season']=='2021' and r['pick']=='3')
assert raw['pfr_player_id']=='LancTr00' and raw['pfr_player_name']=='Trey Lance' and raw['team']=='SFO'
proposal={'schemaVersion':1,'aliasArtifactVersion':'audited-postdraft-reference-aliases-v1','status':'staged-not-applied','createdOn':'2026-11-20','scope':'Historical reference identity normalization only; must not be loaded by live runtime or pre-draft feature generation.','expectedInput':{'scenarioPath':str(scenarioPath.relative_to(ROOT)),'scenarioVersion':scenario['metadata']['version'],'scenarioSha256':sha(scenarioPath),'informationCutoff':scenario['metadata']['informationCutoff'],'rawDraftPath':str(rawPath.relative_to(ROOT)),'rawDraftSha256':sha(rawPath)},'aliases':[{'aliasId':'trey-lance-2021-reference-identity-v1','reviewGroupId':'cross-pool-040','draftYear':2021,'fromProspectId':alias,'toCanonicalProspectId':canonical,'canonicalName':'Trey Lance','canonicalSchool':'North Dakota State','referenceSchoolAlias':'North Dakota St.','externalIdentity':{'pfrPlayerId':'LancTr00','gsisId':'00-0037012'},'expectedHistoricalSelection':actual,'evidenceSourceIds':['sf-trey-2021','ndsu-trey-2021'],'decision':'audited-same-person','evidenceTiming':'post-selection; not eligible pre-draft evidence','preDraftFeatureAllowed':False,'eligibilityInferenceAllowed':False,'measurementMergeAllowed':False,'projectionMutationAllowed':False,'applyOnlyTo':'postdraft-reference identity join during a new explicitly versioned regeneration','rationale':'Both primary reports identify the same school, name, quarterback role, draft year, selecting franchise and overall pick; the existing playable invitee identity already exists.','expectedEffectIfLaterApplied':{'actualPick3ProspectId':canonical,'playablePoolCountChange':0,'unmergedReferenceOnlyIdentityCountChange':-1},'preservedCanonicalRecord':{k:byid[canonical][k]for k in ['id','name','position','college','source','availableBy','eligibilitySource','playable']},'preservedAliasRecord':{k:byid[alias][k]for k in ['id','name','position','college','source','availableBy','eligibilitySource','playable']}}],'sourceProvenance':[s for s in SOURCES if s['sourceId']in ['sf-trey-2021','ndsu-trey-2021']],'regenerationRequirements':['Require exact input version/hash and source-ID guards or explicitly re-audit if inputs changed.','Never rewrite existing runs, frozen datasets, model versions, leaderboards or current gameplay.','Use a new scenario/model-reference version and rebuild historical references; retain an old-to-new identity migration manifest.','Keep official invitee membership and pre-draft measurement availability unchanged; this postdraft evidence cannot create eligible players or backfill measurements.','Recheck baseline uniqueness, canonical references, projections and comparative results after regeneration.','Exclude distinct-people groups and every unverified spelling/unresolved suggestion from alias application.']}
(OUT/'audited_postdraft_reference_aliases.json').write_text(json.dumps(proposal,indent=2)+'\n')
(OUT/'validation.json').write_text(json.dumps({'groups':len(classified),'classificationCounts':counts,'stagedAuditedAliases':1,'aliasFromAndToExist':True,'historicalSelectionGuardMatches':True,'rawExternalIdentityGuardMatches':True,'gameplayOrFrozenWorktreeChangedByThisReview':False,'failures':[]},indent=2)+'\n')
with (OUT/'REVIEW.md').open('w')as f:
 f.write('# Cross-pool identity review\n\nDocumentation only. No runtime, dataset, gameplay or frozen-worktree changes were made.\n\n')
 f.write('All **53** original candidate groups are extracted in `cross_pool_classification.json`. Classification counts: '+', '.join(f'**{v} {k}**'for k,v in counts.items())+'.\n\n')
 f.write('Only Trey Lance is an audited same-person match. The 38 plausible school spelling matches remain suggestions, not aliases approved for application. Unresolved acronym/geographic/historical-name cases remain separate. The two distinct-person groups (David Long, Anthony Johnson) are supported by official team reports and must never be merged on name alone.\n\n')
 f.write('## Staged audited alias\n\n`audited_postdraft_reference_aliases.json` records `p2021-ref-e9aacb6df1` → `p2021-4a3e07404f`, postdraft-reference identity only. Both the [49ers report](https://www.49ers.com/news/49ers-trey-lance-with-the-no-3-pick-in-the-2021-nfl-draft) and [North Dakota State report](https://gobison.com/news/2021/4/29/football-san-francisco-49ers-draft-trey-lance-with-no-3-overall-pick) identify the North Dakota State quarterback Trey Lance as San Francisco’s third overall choice in 2021. The draft record uses North Dakota St.; the existing playable invitee uses North Dakota State. Raw PFR ID LancTr00 and GSIS ID 00-0037012 are recorded as local reference identifiers, not identifiers supplied by those articles.\n\n')
 f.write('The evidence is post-selection. It must never be used to claim pre-draft eligibility, timestamp availability, measured performance or draft information. The existing invitee already establishes the playable identity. If subsequently applied in a new versioned regeneration, this one alias would correct historical pick 3’s identity reference without changing playable pool membership. Nothing is applied now. The artifact includes exact IDs, expected actual pick/team/year, source and raw-input hashes, primary-source provenance and regeneration guards. Original HTML/archive hashes are unavailable and explicitly null; retrieved live-page dates are not proof of original snapshots.\n\n')
 f.write('## All groups\n\n| Group | Year | Name | School pair | Classification | Evidence |\n|---|---:|---|---|---|---|\n')
 for g in classified:f.write(f"| {g['groupId']} | {g['year']} | {g['name']} | {' / '.join(r['college']for r in g['records'])} | {g['classification']} | {g['evidenceStatus']} |\n")
 f.write('\nName-change pairs such as Greg/Gregory Rousseau and Jayson/Odafe Oweh are additional candidates outside the original 53 and are not covered by this alias. Different position labels remain preserved, including S/CB, DE/DL and T/OL differences; a school spelling suggestion must not silently decide position.\n\nReproduce the documentation with `python docs/audit/identity_review/build_review.py`. It reads the committed candidate list and local scenario/raw records and writes only to this directory. `validation.json` records guards and zero failures.\n')
print(json.dumps({'groups':53,'classificationCounts':counts,'aliasesStaged':1,'output':str(OUT)}))
